create or replace function public.publish_live_network_event(p_event_type text,p_location_id uuid default null,p_actor_type text default 'user',p_actor_id uuid default null,p_payload jsonb default '{}'::jsonb) returns uuid language plpgsql security invoker set search_path=public,pg_temp as $$ declare v_id uuid; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if nullif(trim(p_event_type),'') is null then raise exception 'event_type is required'; end if; if p_actor_type not in ('user','business','fleet','enterprise','system') then raise exception 'Invalid actor type'; end if; insert into public.live_network_events(event_type,location_id,actor_type,actor_id,payload) values(trim(p_event_type),p_location_id,p_actor_type,auth.uid(),coalesce(p_payload,'{}'::jsonb)) returning id into v_id; return v_id; end; $$; revoke execute on function public.publish_live_network_event(text,uuid,text,uuid,jsonb) from anon; grant execute on function public.publish_live_network_event(text,uuid,text,uuid,jsonb) to authenticated; drop policy if exists live_network_events_select_authenticated on public.live_network_events; create or replace function public.list_public_live_network_events(p_limit integer default 30) returns table(id uuid,event_type text,created_at timestamptz) language sql security definer set search_path=public,pg_temp as $$ select e.id,e.event_type,e.created_at from public.live_network_events e where e.event_type in ('location.verified','location.stale','location.conflict','business.offer_started','business.offer_redeemed','business.campaign_converted') and e.created_at <= now()-interval '1 hour' order by e.created_at desc limit least(greatest(coalesce(p_limit,30),1),100); $$; revoke execute on function public.list_public_live_network_events(integer) from anon; grant execute on function public.list_public_live_network_events(integer) to authenticated; create or replace function public.record_fleet_operational_event(p_business_id uuid,p_event_type text,p_payload jsonb default '{}'::jsonb) returns uuid language plpgsql security invoker set search_path=public,pg_temp as $$ declare v_id uuid; v_vehicle uuid; v_driver uuid; v_route uuid; v_value numeric; v_lat double precision; v_lng double precision; v_occurred timestamptz; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if p_business_id is null or nullif(trim(p_event_type),'') is null then raise exception 'business_id and event_type are required'; end if; if not exists(select 1 from public.business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid()) and not is_platform_owner(auth.uid()) then raise exception 'Fleet business authorization required'; end if; v_vehicle:=case when coalesce(p_payload->>'vehicle_id',p_payload->>'vehicleId') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then (coalesce(p_payload->>'vehicle_id',p_payload->>'vehicleId'))::uuid else null end; v_driver:=case when coalesce(p_payload->>'driver_id',p_payload->>'driverId') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then (coalesce(p_payload->>'driver_id',p_payload->>'driverId'))::uuid else null end; v_route:=case when coalesce(p_payload->>'route_id',p_payload->>'routeId') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then (coalesce(p_payload->>'route_id',p_payload->>'routeId'))::uuid else null end; v_value:=case when coalesce(p_payload->>'event_value',p_payload->>'eventValue') ~ '^-?[0-9]+(\\.[0-9]+)?$' then (coalesce(p_payload->>'event_value',p_payload->>'eventValue'))::numeric else null end; v_lat:=case when coalesce(p_payload->>'latitude') ~ '^-?[0-9]+(\\.[0-9]+)?$' then (p_payload->>'latitude')::double precision else null end; v_lng:=case when coalesce(p_payload->>'longitude') ~ '^-?[0-9]+(\\.[0-9]+)?$' then (p_payload->>'longitude')::double precision else null end; v_occurred:=case when coalesce(p_payload->>'occurred_at',p_payload->>'occurredAt') is not null then (coalesce(p_payload->>'occurred_at',p_payload->>'occurredAt'))::timestamptz else now() end; insert into public.fleet_operational_events(business_id,vehicle_id,driver_id,route_id,event_type,event_value,unit,latitude,longitude,occurred_at,metadata) values(p_business_id,v_vehicle,v_driver,v_route,trim(p_event_type),v_value,p_payload->>'unit',v_lat,v_lng,v_occurred,coalesce(p_payload->'metadata','{}'::jsonb)||jsonb_build_object('actor_user_id',auth.uid(),'server_authoritative',true)); return (select id from public.fleet_operational_events where business_id=p_business_id and event_type=trim(p_event_type) and occurred_at=v_occurred order by id desc limit 1); end; $$; revoke execute on function public.record_fleet_operational_event(uuid,text,jsonb) from anon; grant execute on function public.record_fleet_operational_event(uuid,text,jsonb) to authenticated; drop policy if exists fleet_operational_events_insert_access on public.fleet_operational_events; create policy fleet_operational_events_insert_access on public.fleet_operational_events for insert to authenticated with check (exists(select 1 from public.business_members bm where bm.business_id=fleet_operational_events.business_id and bm.user_id=auth.uid()) or is_platform_owner(auth.uid()));
